blocs/basic/basic-button/style.css.content:
:host {
    display: inline-block;
    max-width: 100%;
    font: inherit;
    color: inherit;
    vertical-align: middle;
    --_button-background: var(--_tone-base);
    --_button-color: var(--_tone-foreground);
    --_button-border: var(--_tone-border);
    --_button-hover-background: color-mix(
        in srgb,
        var(--cms-button-background, var(--_tone-base)) 88%,
        Canvas
    );
}

[part="control"] {
    display: inline-grid;
    position: relative;
    align-items: center;
    max-width: 100%;
}

slot[name="icon-start"],
slot[name="icon-end"] {
    display: inline-flex;
    position: absolute;
    z-index: 1;
    top: 50%;
    align-items: center;
    justify-content: center;
    color: var(--cms-button-color, var(--_button-color));
    pointer-events: none;
    transform: translateY(-50%);
}

slot[name="icon-start"] {
    inset-inline-start: var(--cms-button-icon-offset, 1rem);
}

slot[name="icon-end"] {
    inset-inline-end: var(--cms-button-icon-offset, 1rem);
}

::slotted(svg[slot="icon-start"]),
::slotted(svg[slot="icon-end"]) {
    display: block;
    width: var(--cms-button-icon-size, 1.15em);
    height: var(--cms-button-icon-size, 1.15em);
    color: inherit;
    pointer-events: none;
}

::slotted(a),
::slotted(button) {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: var(--cms-button-alignment, center);
    gap: var(--cms-button-gap, .5rem);
    min-height: var(--cms-button-min-height, var(--integration-basic-blocs-action-min-height, 2.5rem));
    margin: 0;
    padding: var(--cms-button-padding, .625rem 1rem);
    border: var(--cms-button-border, 1px solid var(--cms-button-border-color, var(--_button-border)));
    border-radius: var(--cms-button-radius, var(--integration-basic-blocs-action-radius, .375rem));
    background: var(--cms-button-background, var(--_button-background));
    color: var(--cms-button-color, var(--_button-color)) !important;
    font: inherit;
    font-weight: var(--cms-button-font-weight, 700) !important;
    line-height: 1.2 !important;
    text-align: center;
    text-decoration: none !important;
    cursor: pointer;
    transition: background-color 120ms ease, border-color 120ms ease, color 120ms ease, transform 120ms ease;
}

::slotted(a:hover),
::slotted(button:hover:not(:disabled)) {
    background: var(--cms-button-hover-background, var(--_button-hover-background));
}

::slotted(a:active),
::slotted(button:active:not(:disabled)) {
    transform: translateY(1px);
}

::slotted(a:focus-visible),
::slotted(button:focus-visible) {
    outline: 2px solid var(--cms-focus-color, var(--_tone-focus));
    outline-offset: 2px;
}

::slotted(button:disabled) {
    cursor: not-allowed;
    opacity: .6;
}

:host([appearance="soft"]) {
    --_button-background: var(--_tone-muted);
    --_button-color: var(--_tone-contrasted);
    --_button-border: var(--_tone-muted);
    --_button-hover-background: color-mix(in srgb, var(--_tone-muted) 88%, var(--_tone-contrasted));
}

:host([appearance="outlined"]) {
    --_button-background: transparent;
    --_button-color: var(--_tone-contrasted);
    --_button-border: var(--_tone-border);
    --_button-hover-background: color-mix(
        in srgb,
        var(--cms-button-color, var(--_button-color)) 10%,
        transparent
    );
}

:host([appearance="ghost"]) {
    --_button-background: transparent;
    --_button-color: var(--_tone-contrasted);
    --_button-border: transparent;
    --_button-hover-background: color-mix(
        in srgb,
        var(--cms-button-color, var(--_button-color)) 10%,
        transparent
    );
}

:host([size="xs"]) ::slotted(a),
:host([size="xs"]) ::slotted(button) { min-height: 1.9rem; padding: .3rem .7rem; font-size: .78rem; }
:host([size="sm"]) ::slotted(a),
:host([size="sm"]) ::slotted(button) { min-height: 2.2rem; padding: .45rem .9rem; font-size: .85rem; }
:host([size="lg"]) ::slotted(a),
:host([size="lg"]) ::slotted(button) { min-height: 3rem; padding: .8rem 1.6rem; font-size: 1.05rem; }
:host([size="xl"]) ::slotted(a),
:host([size="xl"]) ::slotted(button) { min-height: 3.4rem; padding: 1rem 2rem; font-size: 1.15rem; }

:host([has-icon-start]) ::slotted(a),
:host([has-icon-start]) ::slotted(button) {
    padding-inline-start: var(--cms-button-icon-padding, 2.75rem);
}

:host([has-icon-end]) ::slotted(a),
:host([has-icon-end]) ::slotted(button) {
    padding-inline-end: var(--cms-button-icon-padding, 2.75rem);
}

:host([width="full"]) { display: block; }
:host([width="full"]) [part="control"] { display: grid; width: 100%; }
:host([width="full"]) ::slotted(a),
:host([width="full"]) ::slotted(button) { display: flex; width: 100%; }
:host([align="left"]) { --cms-button-alignment: flex-start; }
:host([align="right"]) { --cms-button-alignment: flex-end; }

@media (prefers-reduced-motion: reduce) {
    ::slotted(a),
    ::slotted(button) { transition: none; }
}

