    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
}

.label-section {
    display: inline-flex;
    align-items: center;
    gap: 0.3125rem;
    padding: 0;
    margin: 0;
    color: inherit;
    font: inherit;
    cursor: default;
    background: none;
    border: 0;
}

:host([sort]) .label-section {
    cursor: pointer;
}

.sort-icon {
    display: none;
}

:host([sort]) .sort-icon {
    display: inline;
