    content: "↑";
}

:host([aria-sort="descending"]) .sort-icon {
    font-size: 0;
}

:host([aria-sort="descending"]) .sort-icon::before {
    font-size: var(--integration-basic-blocs-table-font-size, 0.875rem);
    content: "↓";
}

.filter-trigger {
