    background: transparent;
    border: 0;
    border-radius: 0.25rem;
}

:host([data-has-filter]) .filter-trigger {
    color: var(--primary-base, #175cd3);
}

.filter-trigger:hover {
    background: var(--bg-base, color-mix(in srgb, currentColor 6%, transparent));
}

.filter-popover {
    position: absolute;
    top: 100%;
    left: 0;
    z-index: 10;
    min-width: 9.375rem;
    padding: 0.625rem;
    background: var(--integration-basic-blocs-surface-background, var(--bg-surface, Canvas));
    border: 1px solid var(--border-default, color-mix(in srgb, currentColor 20%, transparent));
    border-radius: 0.375rem;
    box-shadow: var(--integration-basic-blocs-elevated-shadow, 0 0.25rem 0.75rem rgb(0 0 0 / 10%));
}

.filter-popover[hidden],
.filter-trigger[hidden] {
    display: none;
}

input {
    box-sizing: border-box;
    width: 100%;
    padding: 0.375rem;
    color: var(--text-main, CanvasText);
    font: inherit;
    background: var(--bg-surface, Canvas);
    border: 1px solid var(--border-default, color-mix(in srgb, currentColor 20%, transparent));
