blocs/feedback/basic-alert/style.css.content:
:host {
    --basic-alert-background: var(--_tone-muted);
    --basic-alert-color: var(--_tone-contrasted);
    --basic-alert-accent: var(--_tone-base);
    --basic-alert-border: var(--_tone-border);

    display: block;
    color: var(--basic-alert-color);

    --ctx-bg: var(--basic-alert-background);
    --ctx-fg: var(--basic-alert-color);
    --ctx-fg-muted: color-mix(in oklab, var(--basic-alert-color) 72%, var(--basic-alert-background));
    --ctx-border: var(--basic-alert-border);
}

:host([hidden]) { display: none !important; }

:host([appearance="filled"]) {
    --basic-alert-background: var(--_tone-base);
    --basic-alert-color: var(--_tone-foreground);
    --basic-alert-accent: var(--_tone-foreground);
}

:host([appearance="outlined"]) {
    --basic-alert-background: transparent;
}

:host([appearance="ghost"]) {
    --basic-alert-background: transparent;
    --basic-alert-border: transparent;
}

.alert {
    display: flex;
    align-items: flex-start;
    gap: var(--space-sm, .5rem);
    padding: var(--space-md, 1rem);
    border: 1px solid var(--basic-alert-border);
    border-inline-start-width: .25rem;
    border-radius: var(--integration-basic-blocs-surface-radius, var(--radius-card, .5rem));
    background: var(--basic-alert-background);
    color: inherit;
    line-height: 1.45;
}

.icon {
    display: inline-flex;
    flex: 0 0 auto;
    align-items: center;
    justify-content: center;
    color: var(--basic-alert-accent);
}

.body {
    flex: 1;
    min-width: 0;
}

.title {
    margin-block-end: .25rem;
    font-weight: 700;
}

.title ::slotted(*),
.message ::slotted(*) {
    margin-block: 0;
}

.close {
    flex: 0 0 auto;
    margin: -.25rem -.25rem 0 0;
    padding: .125rem .25rem;
    border: 0;
    background: transparent;
    color: inherit;
    cursor: pointer;
    font: inherit;
    font-size: 1.25rem;
    line-height: 1;
    opacity: .65;
}

.close:hover { opacity: 1; }
.close:focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
[hidden] { display: none !important; }

