:host {
    --basic-badge-background: var(--_tone-muted);
    --basic-badge-color: var(--_tone-contrasted);
    --basic-badge-border: transparent;
    --basic-badge-font-size: .875rem;
    --basic-badge-padding: .15rem .5rem;

    display: inline-flex;
    max-inline-size: 100%;

    --ctx-bg: var(--basic-badge-background);
    --ctx-fg: var(--basic-badge-color);
    --ctx-fg-muted: var(--basic-badge-color);
    --ctx-border: var(--basic-badge-border);
}

:host([hidden]) { display: none !important; }

:host([appearance="filled"]) {
    --basic-badge-background: var(--_tone-base);
    --basic-badge-color: var(--_tone-foreground);
}

:host([appearance="outlined"]) {
    --basic-badge-background: transparent;
    --basic-badge-color: var(--_tone-contrasted);
    --basic-badge-border: var(--_tone-border);
}

:host([appearance="ghost"]) {
    --basic-badge-background: transparent;
    --basic-badge-color: var(--_tone-contrasted);
}

:host([size="sm"]) {
    --basic-badge-font-size: .75rem;
    --basic-badge-padding: .1rem .4rem;
}

:host([size="lg"]) {
    --basic-badge-font-size: 1rem;
    --basic-badge-padding: .25rem .7rem;
}

.badge {
    display: inline-flex;
    max-inline-size: 100%;
    align-items: center;
    gap: .35rem;
    padding: var(--basic-badge-padding);
    overflow: hidden;
    border: 1px solid var(--basic-badge-border);
    border-radius: 999px;
    background: var(--basic-badge-background);
    color: var(--basic-badge-color);
    font-size: var(--basic-badge-font-size);
    font-weight: 650;
    line-height: 1.2;
    white-space: nowrap;
}

.dot {
    display: none;
    flex: 0 0 auto;
    width: .375rem;
    height: .375rem;
    border-radius: 50%;
    background: var(--basic-badge-dot-color, currentColor);
}

:host([dot]:not([dot="false"])) .dot { display: inline-block; }

.content {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
}

