import { basicColorSchemeCss } from "./colorSchemes";

class BasicInput extends HTMLElement {
    static formAssociated = true;
    static observedAttributes = [
        "autocomplete",
        "accent-color",
        "background-color",
        "border-color",
        "date-format",
        "disabled",
        "hint",
        "invalid-date-message",
        "label",
        "max",
        "maxlength",
        "min",
        "minlength",
        "name",
        "pattern",
        "placeholder",
        "readonly",
        "required",
        "step",
        "text-color",
        "type",
        "value",
    ];

    constructor() {
        super();
        this.root = this.attachShadow({ mode: "open" });
        this.internals = this.attachInternals();
        this.defaultValue = "";
        this.defaultsCaptured = false;
        this.showValidation = false;
        this.dayFirstDate = false;
        // Grid stretch sizes the outer box. Percentage sizing overflows padded native
        // date/time controls on iOS Safari (WebKit bug 301648).
        this.root.innerHTML = `
            <style>
                ${basicColorSchemeCss()}
                :host {
                    --_field-background: var(--integration-basic-blocs-field-background, Canvas);
                    --_field-border: var(--integration-basic-blocs-field-border, color-mix(in srgb, currentColor 25%, transparent));
                    --_field-color: var(--integration-basic-blocs-field-text, inherit);
                    display: block;
                    box-sizing: border-box;
                    min-width: 0;
                    min-inline-size: 0;
                    max-width: 100%;
                    max-inline-size: 100%;
                    font: inherit;
                    color: inherit;
                }
                :host([appearance="soft"]) {
                    --_field-background: var(--_tone-muted);
                    --_field-border: var(--_tone-muted);
                    --_field-color: var(--_tone-contrasted);
                }
                :host([appearance="filled"]) {
                    --_field-background: var(--_tone-base);
                    --_field-border: var(--_tone-base);
                    --_field-color: var(--_tone-foreground);
                }
                :host([appearance="outlined"]) {
                    --_field-border: var(--_tone-border);
                    --_field-color: var(--_tone-contrasted);
                }
                :host([appearance="ghost"]) {
                    --_field-background: transparent;
                    --_field-border: transparent;
                    --_field-color: var(--_tone-contrasted);
                }
                :host([hidden]) { display: none !important; }
                .field { display: grid; grid-template-columns: minmax(0, 1fr); min-width: 0; min-inline-size: 0; gap: var(--cms-field-gap, .375rem); }
                label { font: inherit; font-weight: var(--cms-label-weight, 650); }
                input { box-sizing: border-box; width: auto; inline-size: auto; min-width: 0; min-inline-size: 0; max-width: 100%; max-inline-size: 100%; justify-self: stretch; min-height: var(--cms-input-height, 2.75rem); padding: var(--cms-input-padding, .65rem .75rem); border: var(--cms-input-border, 1px solid var(--cms-input-border-color, var(--_field-border))); border-radius: var(--cms-input-radius, var(--integration-basic-blocs-field-radius, .5rem)); background: var(--cms-input-background, var(--_field-background)); color: var(--cms-input-color, var(--_field-color)); font: inherit; }
                input:focus-visible { outline: 2px solid var(--cms-focus-color, var(--_tone-focus)); outline-offset: 2px; }
                :host([disabled]) { opacity: .6; }
                .hint { color: var(--cms-muted-color, var(--integration-basic-blocs-muted-text, color-mix(in srgb, currentColor 65%, transparent))); }
                .error { color: var(--cms-error-color, var(--integration-basic-blocs-error-text, #b42318)); }
                [hidden] { display: none; }
            </style>
            <div class="field" part="field">
                <label part="label" for="control"></label>
                <input id="control" part="input">
                <small class="hint" part="hint"></small>
                <small class="error" part="error" aria-live="polite"></small>
            </div>`;
        this.fieldElement = this.root.querySelector(".field");
        this.input = this.root.querySelector("input");
        this.labelElement = this.root.querySelector("label");
        this.hintElement = this.root.querySelector(".hint");
        this.errorElement = this.root.querySelector(".error");
    }

    connectedCallback() {
        if (!this.defaultsCaptured) {
            this.defaultValue = this.getAttribute("value") || "";
            this.defaultsCaptured = true;
        }
        this.input.addEventListener("input", this.onInput);
        this.input.addEventListener("change", this.onChange);
        this.input.addEventListener("keydown", this.onKeydown);
        this.addEventListener("invalid", this.onInvalid);
        this.sync();
    }

    disconnectedCallback() {
        this.input.removeEventListener("input", this.onInput);
        this.input.removeEventListener("change", this.onChange);
        this.input.removeEventListener("keydown", this.onKeydown);
        this.removeEventListener("invalid", this.onInvalid);
    }

    attributeChangedCallback() {
        if (this.isConnected) {
            this.sync();
        }
    }

    formResetCallback() {
        this.showValidation = false;
        this.value = this.defaultValue;
    }
    formDisabledCallback(disabled) {
        this.disabled = disabled;
    }

    get value() {
        return this.serializeValue();
    }
    set value(value) {
        this.input.value = this.dayFirstDate ? formatDayFirstDate(value) : value == null ? "" : String(value);
        this.internals.setFormValue(this.disabled ? null : this.serializeValue());
        this.syncValidity();
    }
    get name() {
        return this.getAttribute("name") || "";
    }
    set name(value) {
        value ? this.setAttribute("name", value) : this.removeAttribute("name");
    }
    get disabled() {
        return this.hasAttribute("disabled");
    }
    set disabled(value) {
        this.toggleAttribute("disabled", Boolean(value));
    }
    get required() {
        return this.hasAttribute("required");
    }
    set required(value) {
        this.toggleAttribute("required", Boolean(value));
    }
    focus(options) {
        this.input.focus(options);
    }

    sync() {
        this.syncColors();
        this.labelElement.textContent = this.getAttribute("label") || "";
        this.labelElement.hidden = !this.labelElement.textContent;
        this.hintElement.textContent = this.getAttribute("hint") || "";
        this.hintElement.hidden = !this.hintElement.textContent;
        const type = this.getAttribute("type") || "text";
        const wasDayFirstDate = this.dayFirstDate;
        this.dayFirstDate = type === "date" && this.getAttribute("date-format") === "day-month-year";
        this.input.type = this.dayFirstDate ? "text" : type === "datetime" ? "datetime-local" : type;
        if (this.dayFirstDate) {
            this.input.inputMode = "numeric";
        } else {
            this.input.removeAttribute("inputmode");
        }
        for (const name of ["autocomplete", "max", "maxlength", "min", "minlength", "pattern", "placeholder", "step"]) {
            const value = this.getAttribute(name);
            if (value === null) {
                this.input.removeAttribute(name);
            } else {
                this.input.setAttribute(name, value);
            }
        }
        for (const name of ["disabled", "readonly", "required"]) {
            this.input.toggleAttribute(name, this.hasAttribute(name));
        }
        const value = this.getAttribute("value");
        if (value !== null && (wasDayFirstDate !== this.dayFirstDate || value !== this.value)) {
            this.input.value = this.dayFirstDate ? formatDayFirstDate(value) : value;
        }
        this.internals.setFormValue(this.disabled ? null : this.serializeValue());
        this.syncValidity();
    }

    syncColors() {
        for (const [attribute, property] of [
            ["accent-color", "--cms-focus-color"],
            ["background-color", "--cms-input-background"],
            ["border-color", "--cms-input-border-color"],
            ["text-color", "--cms-input-color"],
        ]) {
            const value = this.getAttribute(attribute)?.trim();
            if (value) {
                this.fieldElement.style.setProperty(property, value);
            } else {
                this.fieldElement.style.removeProperty(property);
            }
        }
    }

    syncValidity() {
        const serializedDate = this.dayFirstDate && this.input.value ? parseDayFirstDate(this.input.value) : null;
        const invalidFormattedDate = this.dayFirstDate && Boolean(this.input.value) && !serializedDate;
        const belowMinimum =
            serializedDate && this.getAttribute("min") ? serializedDate < this.getAttribute("min") : false;
        const aboveMaximum =
            serializedDate && this.getAttribute("max") ? serializedDate > this.getAttribute("max") : false;

        const dateValidationMessage =
            invalidFormattedDate || belowMinimum || aboveMaximum
                ? this.getAttribute("invalid-date-message") || "Enter a valid date in DD/MM/YYYY format."
                : "";

        if (this.disabled || (this.input.validity.valid && !dateValidationMessage)) {
            this.internals.setValidity({});
        } else if (dateValidationMessage) {
            this.internals.setValidity({ customError: true }, dateValidationMessage, this.input);
        } else {
            this.internals.setValidity(this.input.validity, this.input.validationMessage, this.input);
        }
        this.errorElement.textContent = this.showValidation
            ? dateValidationMessage || this.input.validationMessage || ""
            : "";
        this.errorElement.hidden = !this.errorElement.textContent;
    }

    onInput = () => {
        this.internals.setFormValue(this.disabled ? null : this.serializeValue());
        this.syncValidity();
        this.dispatchEvent(new Event("input", { bubbles: true, composed: true }));
    };
    onChange = () => {
        this.internals.setFormValue(this.disabled ? null : this.serializeValue());
        this.syncValidity();
        this.dispatchEvent(new Event("change", { bubbles: true, composed: true }));
    };
    onInvalid = () => {
        this.showValidation = true;
        this.syncValidity();
    };
    onKeydown = (event) => {
        if (
            event.key !== "Enter" ||
            event.isComposing ||
            event.defaultPrevented ||
            event.altKey ||
            event.ctrlKey ||
            event.metaKey ||
            event.shiftKey ||
            this.disabled ||
            this.hasAttribute("readonly")
        ) {
            return;
        }

        const form = this.internals.form || this.closest("form");
        if (!form) {
            return;
        }
        event.preventDefault();
        form.requestSubmit();
    };

    serializeValue() {
        if (!this.dayFirstDate || !this.input.value) {
            return this.input.value;
        }
        return parseDayFirstDate(this.input.value) || this.input.value;
    }
}

function formatDayFirstDate(value) {
    const normalized = value == null ? "" : String(value).trim();
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(normalized);
    return match ? `${match[3]}/${match[2]}/${match[1]}` : normalized;
}

function parseDayFirstDate(value) {
    const match = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(String(value).trim());
    if (!match) {
        return null;
    }
    const isoDate = `${match[3]}-${match[2]}-${match[1]}`;
    const date = new Date(`${isoDate}T00:00:00Z`);
    return Number.isNaN(date.getTime()) || date.toISOString().slice(0, 10) !== isoDate ? null : isoDate;
}

