    --ctx-fg-muted: color-mix(in srgb, var(--basic-grid-color) 68%, transparent);
    --ctx-border: var(--_tone-border);

    display: grid;
    box-sizing: border-box;
    width: 100%;
    grid-template-columns: repeat(auto-fill, minmax(min(var(--basic-grid-min), 100%), 1fr));
    gap: var(--basic-grid-gap);
