}

:host([appearance="plain"]) {
    --basic-grid-color: var(--_tone-contrasted);
}

:host([appearance="filled"]) {
    --basic-grid-background: var(--_tone-base);
    --basic-grid-color: var(--_tone-foreground);
}

:host([packing="fit"]) {
    grid-template-columns: repeat(auto-fit, minmax(min(var(--basic-grid-min), 100%), 1fr));
}

