};

const role = (token: string, system: string, fallbackToken?: string): ThemeColorRole => ({
    token,
    ...(fallbackToken ? { fallbackToken } : {}),
    system,
});

export const BASIC_COLOR_SCHEMES: readonly BasicColorScheme[] = [
    {
        value: "primary",
