}

function roleValue(value: ThemeColorRole): string {
    const fallback = value.fallbackToken
        ? `var(--integration-basic-blocs-${value.fallbackToken}, ${value.system})`
        : value.system;
    return `var(--integration-basic-blocs-${value.token}, ${fallback})`;
}

