type ThemeColorRole = {
    token: string;
    fallbackToken?: string;
    system: string;
};

type BasicColorScheme = {
    value: string;
    label: string;
    roles: {
        base: ThemeColorRole;
        foreground: ThemeColorRole;
        muted: ThemeColorRole;
        contrasted: ThemeColorRole;
        border: ThemeColorRole;
        focus: ThemeColorRole;
    };
};

const role = (token: string, system: string, fallbackToken?: string): ThemeColorRole => ({
    token,
    ...(fallbackToken ? { fallbackToken } : {}),
    system,
});

export const BASIC_COLOR_SCHEMES: readonly BasicColorScheme[] = [
    {
        value: "primary",
        label: "Primary",
        roles: {
            base: role("action-background", "CanvasText", "primary-base"),
            foreground: role("action-text", "Canvas", "primary-foreground"),
            muted: role("action-muted-background", "Canvas", "primary-muted"),
            contrasted: role("action-muted-text", "CanvasText", "primary-contrasted"),
            border: role("action-border", "CanvasText", "primary-base"),
            focus: role("focus-color", "Highlight", "primary-base"),
        },
    },
    scheme("secondary", "Secondary"),
    {
        value: "neutral",
        label: "Neutral",
        roles: {
            base: role("surface-text", "CanvasText"),
            foreground: role("surface-background", "Canvas"),
            muted: role("subtle-background", "Canvas"),
            contrasted: role("surface-text", "CanvasText"),
            border: role("surface-border", "currentColor"),
            focus: role("surface-text", "Highlight"),
        },
    },
    scheme("info", "Information"),
    scheme("success", "Success"),
    scheme("warning", "Warning"),
    scheme("danger", "Danger"),
];

export const BASIC_COLOR_SCHEME_OPTIONS = BASIC_COLOR_SCHEMES.map(({ label, value }) => ({ label, value }));

export function basicColorSchemeCss(defaultTone = "primary"): string {
    return BASIC_COLOR_SCHEMES.map((colorScheme) => {
        const selectors = `${colorScheme.value === defaultTone ? ":host,\n" : ""}:host([tone="${colorScheme.value}"])`;
        const declarations = Object.entries(colorScheme.roles)
            .map(([name, value]) => `    --_tone-${name}: ${roleValue(value)};`)
            .join("\n");
        return `${selectors} {\n${declarations}\n}`;
    }).join("\n\n");
}

function scheme(value: string, label: string): BasicColorScheme {
    return {
        value,
        label,
        roles: {
            base: role(`${value}-base`, "CanvasText"),
            foreground: role(`${value}-foreground`, "Canvas"),
            muted: role(`${value}-muted`, "Canvas"),
            contrasted: role(`${value}-contrasted`, "CanvasText"),
            border: role(`${value}-base`, "currentColor"),
            focus: role(`${value}-base`, "Highlight"),
        },
    };
}

function roleValue(value: ThemeColorRole): string {
    const fallback = value.fallbackToken
        ? `var(--integration-basic-blocs-${value.fallbackToken}, ${value.system})`
        : value.system;
    return `var(--integration-basic-blocs-${value.token}, ${fallback})`;
}

import { trapMenuFocus } from "./focus";

let generatedId = 0;

export class BasicMenuController {
    constructor(host) {
        this.host = host;
        this.connected = false;
        this.lastState = undefined;
        this.previousOverflow = "";
        this.triggerElement = undefined;
        this.onClick = this.onClick.bind(this);
        this.onKeydown = this.onKeydown.bind(this);
        this.onSlotChange = this.onSlotChange.bind(this);
    }

    connect() {
        if (this.connected) {
            return;
        }
        this.connected = true;
        this.host.addEventListener("click", this.onClick);
        this.host.ownerDocument.addEventListener("keydown", this.onKeydown);
        this.host.shadowRoot?.addEventListener("slotchange", this.onSlotChange);
        this.sync();
    }

    disconnect() {
        this.connected = false;
        this.host.removeEventListener("click", this.onClick);
        this.host.ownerDocument.removeEventListener("keydown", this.onKeydown);
        this.host.shadowRoot?.removeEventListener("slotchange", this.onSlotChange);
        this.unlockScroll();
    }

    open() {
        if (this.trigger()) {
            this.host.setAttribute("open", "");
        }
    }

    close() {
        this.host.removeAttribute("open");
    }

    toggle() {
        if (this.host.hasAttribute("open")) {
            this.close();
        } else {
            this.open();
        }
    }

    sync() {
        const open = this.host.hasAttribute("open");
        const panel = this.panel();
        const trigger = this.trigger();
        const panelId = this.panelId();
        panel?.setAttribute("id", panelId);
        panel?.setAttribute("aria-hidden", String(!open));
        panel?.setAttribute("aria-label", this.host.getAttribute("navigation-label")?.trim() || "Menu navigation");
        const closeLabel = this.host.getAttribute("close-label")?.trim() || "Close";
        this.host.shadowRoot?.querySelector("[data-close-label]")?.replaceChildren(closeLabel);
        if (trigger) {
            trigger.setAttribute("aria-expanded", String(open));
            trigger.setAttribute("aria-haspopup", "dialog");
            this.linkAriaControl(trigger, panel);
        }
        if (open) {
            this.lockScroll();
            requestAnimationFrame(() => panel?.focus());
        } else {
            this.unlockScroll();
            if (this.lastState === true) {
                this.triggerElement?.focus();
            }
        }
        if (open !== this.lastState) {
            this.lastState = open;
            this.host.dispatchEvent(
                new CustomEvent("basic-menu-state", {
                    bubbles: true,
                    composed: true,
                    detail: { id: this.host.id, open },
                }),
            );
        }
    }

    onClick(event) {
        const path = event.composedPath();
        const trigger = this.trigger();
        if (trigger && path.includes(trigger)) {
            event.preventDefault();
            this.triggerElement = trigger;
            this.toggle();
            return;
        }
        const closes = path.some(
            (candidate) => candidate instanceof Element && candidate.hasAttribute("data-menu-close"),
        );
        const navigation = path.some(
            (candidate) => candidate instanceof HTMLAnchorElement && candidate.getAttribute("slot") === "navigation",
        );
        if (closes || (navigation && this.host.getAttribute("close-on-navigation") !== "off")) {
            this.close();
        }
    }

    onKeydown(event) {
        if (!this.host.hasAttribute("open")) {
            return;
        }
        if (event.key === "Escape") {
            event.preventDefault();
            this.close();
            return;
        }
        if (event.key !== "Tab") {
            return;
        }
        trapMenuFocus(this.host, event, this.trigger());
    }

    onSlotChange() {
        this.triggerElement = undefined;
        this.sync();
    }

    trigger() {
        const assigned = this.host.querySelector(':scope > [slot="trigger"]');
        if (assigned instanceof HTMLButtonElement) {
            return assigned;
        }
        if (assigned?.localName === "basic-button") {
            const button = assigned.querySelector(":scope > button");
            return button instanceof HTMLButtonElement ? button : undefined;
        }
        return undefined;
    }

    panel() {
        return this.host.shadowRoot?.querySelector('[part="panel"]');
    }

    panelId() {
        if (!this.host.id) {
            generatedId += 1;
            this.host.id = `basic-menu-${generatedId}`;
        }
        return `${this.host.id}-panel`;
    }

    linkAriaControl(trigger, panel) {
        if (!panel) {
            trigger.removeAttribute("aria-controls");
            return;
        }
        if ("ariaControlsElements" in trigger) {
            trigger.ariaControlsElements = [panel];
            if (trigger.ariaControlsElements?.includes(panel)) {
                return;
            }
        }
        // ID references cannot cross every Shadow DOM implementation. In that
        // case, expose the controlled menu host, which remains in the trigger's
        // document tree and owns the open state and dialog panel.
        trigger.setAttribute("aria-controls", this.host.id);
    }

    lockScroll() {
        const root = this.host.ownerDocument.documentElement;
        if (root.style.overflow !== "hidden") {
            this.previousOverflow = root.style.overflow;
            root.style.overflow = "hidden";
        }
    }

    unlockScroll() {
        const root = this.host.ownerDocument.documentElement;
        if (root.style.overflow === "hidden") {
            root.style.overflow = this.previousOverflow;
        }
    }
}

blocs/navigation/basic-menu/internals/fo.content:
const FOCUSABLE = 'a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])';

export function trapMenuFocus(host, event, trigger) {
    const focusable = [...host.shadowRoot.querySelectorAll(FOCUSABLE), ...host.querySelectorAll(FOCUSABLE)].filter(
        (element) => element !== trigger && !element.hasAttribute("hidden"),
    );
    const first = focusable[0];
    const last = focusable.at(-1);
    const active = host.shadowRoot?.activeElement || host.ownerDocument.activeElement;
    if (!first || !last) {
        event.preventDefault();
    } else if (event.shiftKey && active === first) {
        event.preventDefault();
        last.focus();
    } else if (!event.shiftKey && active === last) {
        event.preventDefault();
        first.focus();
    }
}

