    --_color: var(--basic-menu-color, var(--_tone-base));
    --_duration: 620ms;
    --_muted: var(--basic-menu-muted, color-mix(in srgb, var(--_color) 68%, transparent));

    display: inline-block;
    color: inherit;
    font: inherit;
    vertical-align: middle;
}

:host([hidden]) { display: none !important; }
:host([motion="snappy"]) { --_duration: 320ms; }
:host([motion="none"]) { --_duration: 1ms; }

[part="trigger-shell"] {
    display: inline-grid;
    position: relative;
    align-items: center;
    color: inherit;
}

::slotted(basic-button[slot="trigger"]) {
    color: inherit;
}

::slotted(button[slot="trigger"]) {
    min-height: 2.75rem;
    padding: .625rem 1rem;
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    cursor: pointer;
}

[part="layer"] {
    position: fixed;
    z-index: 100;
    inset: 0;
    visibility: hidden;
    color: var(--_color);
    font-family: var(--integration-basic-blocs-font-body, system-ui, sans-serif);
    pointer-events: none;
    transition: visibility 0s var(--_duration);
}

:host([open]) [part="layer"] { visibility: visible; pointer-events: auto; transition-delay: 0s; }

[part="backdrop"] {
    position: absolute;
    inset: 0;
    background: #050708b8;
    opacity: 0;
    transition: opacity var(--_duration) ease;
}

:host([backdrop="blur"]) [part="backdrop"] { background: #05070880; backdrop-filter: blur(.8rem); }
:host([backdrop="none"]) [part="backdrop"] { background: transparent; }
:host([open]) [part="backdrop"] { opacity: 1; }

[part="panel"] {
    position: absolute;
    display: grid;
    grid-template-rows: auto minmax(0, 1fr) auto;
    box-sizing: border-box;
    overflow: hidden;
    background: radial-gradient(circle at 76% 16%, color-mix(in srgb, var(--_accent) 10%, transparent), transparent 26rem), var(--_background);
    color: inherit;
    outline: none;
    transition: transform var(--_duration) cubic-bezier(.76, 0, .24, 1), opacity var(--_duration) ease;
}

[part="header"],
[part="footer"] {
    display: flex;
    justify-content: space-between;
