:host {
    --_navbar-background: transparent;
    --_navbar-border: transparent;
    --_navbar-color: var(--_tone-contrasted);
    --_navbar-panel-background: var(--integration-basic-blocs-surface-background, Canvas);
    --_navbar-action-background: var(--_tone-base);
    --_navbar-action-color: var(--_tone-foreground);
    --_navbar-action-hover-background: color-mix(in srgb, var(--_navbar-action-background) 86%, var(--_navbar-action-color));
    --_navbar-padding-block: var(--integration-basic-blocs-space-sm, .5rem);
    --_navbar-padding-inline: var(--integration-basic-blocs-space-md, 1rem);
    --_navbar-link-padding: .5rem .625rem;
    --ctx-bg: var(--_navbar-background);
    --ctx-fg: var(--_navbar-color);
    --ctx-fg-muted: color-mix(in srgb, var(--_navbar-color) 68%, transparent);
    --ctx-border: var(--_navbar-border);

    position: relative;
    z-index: 10;
    display: block;
    container-type: inline-size;
    color: var(--_navbar-color);
    font: inherit;
}

:host([hidden]) { display: none !important; }

:host([appearance="soft"]) {
    --_navbar-background: var(--_tone-muted);
    --_navbar-border: var(--_tone-muted);
}

:host([appearance="filled"]) {
    --_navbar-background: var(--_tone-base);
    --_navbar-border: var(--_tone-base);
    --_navbar-color: var(--_tone-foreground);
    --_navbar-panel-background: var(--_tone-base);
    --_navbar-action-background: var(--_tone-foreground);
    --_navbar-action-color: var(--_tone-base);
}

:host([appearance="outlined"]) {
    --_navbar-border: var(--_tone-border);
}

:host([density="compact"]) {
    --_navbar-padding-block: var(--integration-basic-blocs-space-xs, .25rem);
    --_navbar-padding-inline: var(--integration-basic-blocs-space-sm, .5rem);
    --_navbar-link-padding: .375rem .5rem;
}

:host([density="spacious"]) {
    --_navbar-padding-block: var(--integration-basic-blocs-space-md, 1rem);
    --_navbar-padding-inline: var(--integration-basic-blocs-space-lg, 1.5rem);
    --_navbar-link-padding: .625rem .75rem;
}

[part="bar"] {
    position: relative;
    display: flex;
    box-sizing: border-box;
    min-height: 3.5rem;
    align-items: center;
    gap: var(--integration-basic-blocs-space-md, 1rem);
    padding: var(--_navbar-padding-block) var(--_navbar-padding-inline);
    border: 1px solid var(--_navbar-border);
    border-radius: var(--integration-basic-blocs-surface-radius, .75rem);
    background: var(--_navbar-background);
    color: var(--_navbar-color);
}

[part="brand"] {
    display: flex;
    min-width: 0;
    align-items: center;
}

::slotted([slot="brand"]) {
    max-width: 100%;
}

::slotted(img[slot="brand"]) {
    width: auto;
    max-height: 2.5rem;
    object-fit: contain;
}

[part="panel"] {
    display: flex;
    min-width: 0;
    flex: 1;
    align-items: center;
    justify-content: flex-end;
    gap: var(--integration-basic-blocs-space-md, 1rem);
}

[part="links"],
[part="actions"] {
    display: flex;
    align-items: center;
    gap: var(--integration-basic-blocs-space-xs, .25rem);
}

[part="toggle"] { display: none; }

::slotted(a:focus-visible) {
    outline: 2px solid var(--_tone-focus);
    outline-offset: 2px;
}

::slotted(a[slot="navigation"]),
::slotted(a[slot="actions"]) {
    --cms-link-color: var(--_navbar-color);

    display: inline-flex;
    align-items: center;
    border-radius: var(--integration-basic-blocs-action-radius, .5rem);
    color: inherit;
    font: inherit;
    text-decoration: none;
    transition: background-color 120ms ease, color 120ms ease, transform 120ms ease;
    white-space: nowrap;
}

::slotted(a[slot="brand"]) {
    --cms-link-color: var(--_navbar-color);

    display: inline-flex;
    align-items: center;
    border-radius: var(--integration-basic-blocs-action-radius, .5rem);
    color: inherit;
    font-family: var(--integration-basic-blocs-font-heading, inherit);
    font-size: 1.125rem;
    font-weight: 700;
    text-decoration: none;
    transition: opacity 120ms ease;
    white-space: nowrap;
}

::slotted(a[slot="brand"]:hover) { opacity: .72; }

::slotted(a[slot="navigation"]) { padding: var(--_navbar-link-padding); }
::slotted(a[slot="navigation"]:hover),
::slotted(a[slot="navigation"][aria-current="page"]) {
    background: color-mix(in srgb, currentColor 10%, transparent);
}

::slotted(a[slot="actions"]) {
    --cms-link-color: var(--_navbar-action-color);

    padding: var(--_navbar-link-padding);
    background: var(--_navbar-action-background);
    color: var(--_navbar-action-color);
    font-weight: 650;
}

::slotted(a[slot="actions"]:hover) {
    background: var(--_navbar-action-hover-background);
    transform: translateY(-1px);
}

::slotted(a[slot="actions"]:active) { transform: translateY(0); }

:host(:not(:has([slot="brand"]))) [part="brand"],
:host(:not(:has([slot="actions"]))) [part="actions"] { display: none; }

@media (prefers-reduced-motion: reduce) {
    ::slotted(a[slot="brand"]),
    ::slotted(a[slot="navigation"]),
    ::slotted(a[slot="actions"]) { transition: none; }
}

export class NavbarLayoutController {
    constructor({ host, bar, brand, links, actions, navigation, slots, onExpanded }) {
        this.host = host;
        this.bar = bar;
        this.brand = brand;
        this.links = links;
        this.actions = actions;
        this.navigation = navigation;
        this.slots = slots;
        this.onExpanded = onExpanded;
        this.resizeObserver = null;
        this.mutationObserver = null;
        this.frame = null;
    }

    connect() {
        this.host.addEventListener("load", this.schedule, true);
        for (const slot of this.slots) {
            slot.addEventListener("slotchange", this.schedule);
        }
        if (globalThis.ResizeObserver) {
            this.resizeObserver = new ResizeObserver(this.schedule);
            for (const element of [this.host, this.brand, this.links, this.actions]) {
                this.resizeObserver.observe(element);
            }
        }
        if (globalThis.MutationObserver) {
            this.mutationObserver = new MutationObserver(this.schedule);
            this.mutationObserver.observe(this.host, {
                attributes: true,
                attributeFilter: ["class", "slot", "style"],
                characterData: true,
                childList: true,
                subtree: true,
            });
        }
        this.schedule();
        this.host.ownerDocument.fonts?.ready.then(this.schedule);
    }

    disconnect() {
        this.host.removeEventListener("load", this.schedule, true);
        for (const slot of this.slots) {
            slot.removeEventListener("slotchange", this.schedule);
        }
        this.resizeObserver?.disconnect();
        this.resizeObserver = null;
        this.mutationObserver?.disconnect();
        this.mutationObserver = null;
        if (this.frame !== null) {
            this.host.ownerDocument.defaultView?.cancelAnimationFrame(this.frame);
            this.frame = null;
        }
    }

    schedule = () => {
        if (this.frame !== null || !this.host.isConnected) {
            return;
        }
        const view = this.host.ownerDocument.defaultView;
        if (!view) {
            this.measure();
            return;
        }
        this.frame = view.requestAnimationFrame(this.measure);
    };

    measure = () => {
        this.frame = null;
        if (!this.host.isConnected) {
            return;
        }
        this.host.removeAttribute("collapsed");
        const collapsed = this.requiredWidth() > this.bar.clientWidth + 1;
        this.host.toggleAttribute("collapsed", collapsed);
        if (!collapsed) {
            this.onExpanded();
        }
    };

    requiredWidth() {
        const barStyle = getComputedStyle(this.bar);
        const panelStyle = getComputedStyle(this.navigation);
        const brandVisible = getComputedStyle(this.brand).display !== "none";
        const actionsVisible = getComputedStyle(this.actions).display !== "none";
        return (
            pixels(barStyle.paddingLeft) +
            pixels(barStyle.paddingRight) +
            (brandVisible ? this.brand.scrollWidth + pixels(barStyle.columnGap) : 0) +
            this.links.scrollWidth +
            (actionsVisible ? pixels(panelStyle.columnGap) + this.actions.scrollWidth : 0)
        );
    }
}

function pixels(value) {
    const parsed = Number.parseFloat(value);
    return Number.isFinite(parsed) ? parsed : 0;
}

:host([collapsed]) [part="toggle"] {
    display: grid;
    width: 2.75rem;
    height: 2.75rem;
    margin-left: auto;
    place-items: center;
    padding: 0;
    border: 1px solid color-mix(in srgb, currentColor 24%, transparent);
    border-radius: var(--integration-basic-blocs-action-radius, .5rem);
    background: transparent;
    color: inherit;
    cursor: pointer;
    transition: background-color 120ms ease;
}

:host([collapsed]) [part="toggle"]:hover {
    background: color-mix(in srgb, currentColor 8%, transparent);
}

:host([collapsed]) [part="toggle"]:focus-visible {
    outline: 2px solid var(--_tone-focus);
    outline-offset: 2px;
}

:host([collapsed]) [part="toggle-icon"] {
    display: grid;
    width: 1.25rem;
    gap: .25rem;
}

:host([collapsed]) [part="toggle-icon"] i {
    display: block;
    height: 2px;
    border-radius: 2px;
    background: currentColor;
    transition: transform 160ms ease, opacity 160ms ease;
}

:host([collapsed][open]) [part="toggle-icon"] i:first-child { transform: translateY(.375rem) rotate(45deg); }
:host([collapsed][open]) [part="toggle-icon"] i:nth-child(2) { opacity: 0; }
:host([collapsed][open]) [part="toggle-icon"] i:last-child { transform: translateY(-.375rem) rotate(-45deg); }

:host([collapsed]) [part="panel"] {
    position: absolute;
    top: calc(100% + var(--integration-basic-blocs-space-xs, .25rem));
    right: 0;
    left: 0;
    display: none;
    box-sizing: border-box;
    justify-content: stretch;
    padding: var(--integration-basic-blocs-space-sm, .5rem);
    border: 1px solid var(--_tone-border);
    border-radius: var(--integration-basic-blocs-surface-radius, .75rem);
    background: var(--_navbar-panel-background);
    box-shadow: var(--integration-basic-blocs-shadow-soft, 0 .5rem 1.5rem color-mix(in srgb, CanvasText 14%, transparent));
    color: var(--_navbar-color);
}

:host([collapsed][open]) [part="panel"] { display: grid; }

:host([collapsed]) [part="links"],
:host([collapsed]) [part="actions"] {
    display: grid;
    align-items: stretch;
    justify-items: stretch;
}

:host([collapsed]) [part="actions"] {
    margin-top: var(--integration-basic-blocs-space-sm, .5rem);
    padding-top: var(--integration-basic-blocs-space-sm, .5rem);
    border-top: 1px solid color-mix(in srgb, currentColor 18%, transparent);
}

:host([collapsed]) ::slotted(a[slot="navigation"]),
:host([collapsed]) ::slotted(a[slot="actions"]) {
    box-sizing: border-box;
    width: 100%;
    justify-content: flex-start;
}

@media (prefers-reduced-motion: reduce) {
    :host([collapsed]) [part="toggle"],
    :host([collapsed]) [part="toggle-icon"] i { transition: none; }
}

